import{_ as a,o as i,c as s,ae as n}from"./chunks/framework.BX_mlWST.js";const u=JSON.parse('{"title":"Factorys & Utilities","description":"","frontmatter":{"title":"Factorys & Utilities","prev":{"text":"General Knowledge","link":"/Main/Main/GeneralKnowledge/main."}},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Liscenses/main.md","filePath":"Main/Main/GeneralKnowledge/Liscenses/main.md"}'),t={name:"Main/Main/GeneralKnowledge/Liscenses/main.md"};function r(o,e,l,c,h,d){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="licenses" tabindex="-1">Licenses <a class="header-anchor" href="#licenses" aria-label="Permalink to &quot;Licenses&quot;">​</a></h1><p>Licenses are a progression system in <strong>Farming And Friends</strong> that allow players to gain access to different vehicles, equipment, animals, and activities.</p><p>There are three license categories:</p><ul><li>🐄 <strong>Animals</strong></li><li>🚜 <strong>Farming</strong></li><li>🚚 <strong>Logistics</strong></li></ul><p>Each license follows the same general progression system, with players completing tasks to earn XP towards their chosen license.</p><h2 id="how-licenses-work" tabindex="-1">How Licenses Work <a class="header-anchor" href="#how-licenses-work" aria-label="Permalink to &quot;How Licenses Work&quot;">​</a></h2><p>Each license requires a certain amount of <strong>License XP</strong> before it can be unlocked.</p><p>Players earn License XP by completing tasks associated with the license.</p><h3 id="task-system" tabindex="-1">Task System <a class="header-anchor" href="#task-system" aria-label="Permalink to &quot;Task System&quot;">​</a></h3><ul><li><strong>4 tasks</strong> are available per cycle.</li><li>Tasks refresh every <strong>2 hours</strong>.</li><li>Completing tasks awards <strong>License XP</strong>.</li><li>Continue completing tasks until the required XP has been reached.</li><li>Once enough XP has been earned, the license can be unlocked.</li></ul><h2 id="license-categories" tabindex="-1">License Categories <a class="header-anchor" href="#license-categories" aria-label="Permalink to &quot;License Categories&quot;">​</a></h2><h3 id="🐄-animals" tabindex="-1">🐄 Animals <a class="header-anchor" href="#🐄-animals" aria-label="Permalink to &quot;🐄 Animals&quot;">​</a></h3><p>Animal licenses cover licenses related to animals and animal-based activities.</p><p><a href="./Animals/main.html">View Animal Licenses</a></p><h3 id="🚜-farming" tabindex="-1">🚜 Farming <a class="header-anchor" href="#🚜-farming" aria-label="Permalink to &quot;🚜 Farming&quot;">​</a></h3><p>Farming licenses cover agricultural equipment, farming activities, and other farming-related operations.</p><p><a href="./Farming/main.html">View Farming Licenses</a></p><h3 id="🚚-logistics" tabindex="-1">🚚 Logistics <a class="header-anchor" href="#🚚-logistics" aria-label="Permalink to &quot;🚚 Logistics&quot;">​</a></h3><p>Logistics licenses cover transportation, delivery, and other logistics-related activities.</p><p><a href="./Logistics/main.html">View Logistics Licenses</a></p><blockquote><p><strong>Note:</strong> License requirements and detailed information will be added as they are documented.</p></blockquote><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="how-often-do-tasks-refresh" tabindex="-1">How often do tasks refresh? <a class="header-anchor" href="#how-often-do-tasks-refresh" aria-label="Permalink to &quot;How often do tasks refresh?&quot;">​</a></h3><p>License tasks refresh every <strong>2 hours</strong>.</p><h3 id="how-many-tasks-are-available" tabindex="-1">How many tasks are available? <a class="header-anchor" href="#how-many-tasks-are-available" aria-label="Permalink to &quot;How many tasks are available?&quot;">​</a></h3><p>There are <strong>4 tasks available during each cycle</strong>.</p><h3 id="can-i-work-on-different-licenses" tabindex="-1">Can I work on different licenses? <a class="header-anchor" href="#can-i-work-on-different-licenses" aria-label="Permalink to &quot;Can I work on different licenses?&quot;">​</a></h3><p>License progression depends on the license selected and the tasks available for it.</p><h3 id="how-much-xp-do-i-need" tabindex="-1">How much XP do I need? <a class="header-anchor" href="#how-much-xp-do-i-need" aria-label="Permalink to &quot;How much XP do I need?&quot;">​</a></h3><p>Each license has its own XP requirement. Check the relevant license page for the exact amount.</p><hr><h3 id="want-to-contribute" tabindex="-1">Want to contribute? <a class="header-anchor" href="#want-to-contribute" aria-label="Permalink to &quot;Want to contribute?&quot;">​</a></h3><p>If you have information about a license, its XP requirement, tasks, or unlocks that isn&#39;t documented yet, consider contributing to the wiki or providing the relevant information to the wiki team.</p>',34)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
